    { 'setting:auras3.boss.buff.filter.includeNameplateOnly@uf_boss/auras/unit-workspace/lane/buff/filters/includenameplateonly', 'menu2.uf_boss.auras.unit-workspace.lane.buff.filters.includenameplateonly', '', '', 'uf_boss', 'auras/unit-workspace/lane/buff/filters/includenameplateonly', 'setting', 'toggle', 'auras3.boss.buff.filter.includeNameplateOnly', '', '', 'direct', 'boolean', '', '', '', '0', '0', '1', 'Also include nameplate-only', 'Blizzard inclusion modifier that broadens the active filter with nameplate-only auras for Boss Buffs. It is evaluated only while Filters Enabled is on; it does not show or hide the aura lane. Available on the Boss Unit Frame page.', '', '', '', '', '', '', '', '', 'unit_boss_buff_filters', '*' },
