    { 'setting:auras3.boss.buff.filter.onlyImportant@uf_boss/auras/unit-workspace/lane/buff/filters/onlyimportant', 'menu2.uf_boss.auras.unit-workspace.lane.buff.filters.onlyimportant', '', '', 'uf_boss', 'auras/unit-workspace/lane/buff/filters/onlyimportant', 'setting', 'toggle', 'auras3.boss.buff.filter.onlyImportant', '', '', 'direct', 'boolean', '', '', '', '0', '0', '1', 'Important', 'Blizzard classification filter for Boss Buffs. It is evaluated only while Filters Enabled is on; it does not show or hide the aura lane. Available on the Boss Unit Frame page.', '', '', '', '', '', '', '', '', 'unit_boss_buff_filters', '*' },
