    { 'setting:auras3.boss.buff.filter.raid@uf_boss/auras/unit-workspace/lane/buff/filters/raid', 'menu2.uf_boss.auras.unit-workspace.lane.buff.filters.raid', '', '', 'uf_boss', 'auras/unit-workspace/lane/buff/filters/raid', 'setting', 'toggle', 'auras3.boss.buff.filter.raid', '', '', 'direct', 'boolean', '', '', '', '0', '0', '1', 'Applicable by me', 'Blizzard classification filter for Boss Buffs. It is evaluated only while Filters Enabled is on; it does not show or hide the aura lane. Available on the Boss Unit Frame page.', '', '', '', '', '', '', '', '', 'unit_boss_buff_filters', '*' },
